"  const updateCartItemQty = (itemId, change) => {
    setCart(prev => prev.map(c => c.id === itemId ? { ...c, quantity: Math.max(1, (c.quantity || 1) + change) } : c));
  };

  const updateCartItemQtyAbsolute = (itemId, qty) => {
    const cleanQty = Math.max(1, parseInt(qty) || 1);
    setCart(prev => prev.map(c => c.id === itemId ? { ...c, quantity: cleanQty } : c));
  };

  const startQtyChange = (itemId, change) => {
    stopQtyChange();
    updateCartItemQty(itemId, change);
    qtyTimeoutRef.current = setTimeout(() => {
      qtyIntervalRef.current = setInterval(() => {
        updateCartItemQty(itemId, change);
      }, 100);
    }, 300);
  };

  const stopQtyChange = () => {
    if (qtyTimeoutRef.current) {
      clearTimeout(qtyTimeoutRef.current);
      qtyTimeoutRef.current = null;
    }
    if (qtyIntervalRef.current) {
      clearInterval(qtyIntervalRef.current);
      qtyIntervalRef.current = null;
    }
  };"
